import {createNativeStackNavigator} from '@react-navigation/native-stack';
import {NavigationName} from '../constants';
import {EvaIconsPack} from '@ui-kitten/eva-icons';
import {ApplicationProvider, IconRegistry} from '@ui-kitten/components';
import * as eva from '@eva-design/eva';
import {default as mapping} from '../../mapping.json';
import React from 'react';
import NotificationListScreen from '../screens/notification/notification-list/ListNotiProcessing';
import NotificationScreen from '../screens/notification/notification-list';
import BottomTabNavigator from './BottomTabNavigator';
import NotificationDetail from '../screens/notification/notification-detail';
import SignatureWebview from '../screens/notification/signature-flow';
import NotificationHistory from '../screens/notification/notification-history';

const Stack = createNativeStackNavigator();

const AppNavigation = () => {
  return (
    <>
      <IconRegistry icons={[EvaIconsPack]} />
      <ApplicationProvider
        customMapping={mapping as any}
        {...eva}
        theme={{...eva.light}}>
        <Stack.Navigator
          screenOptions={{
            headerShown: false,
          }}>
          <Stack.Screen
            name={NavigationName.BottomTabNavigator}
            component={BottomTabNavigator}
          />
          <Stack.Screen
            name={NavigationName.BottomTabNavigation}
            component={BottomTabNavigator}
          />
          <Stack.Screen
            name={NavigationName.NotificationListScreen}
            component={NotificationListScreen}
          />
          <Stack.Screen
            name={NavigationName.SignDozenScreen}
            component={NotificationScreen}
          />
          {/* 
          <Stack.Screen
            name={NavigationName.AccountInfo}
            component={AccountInfo}
          /> */}
          <Stack.Screen
            name={NavigationName.NotificationDetail}
            component={NotificationDetail}
          />
          <Stack.Screen
            name={NavigationName.SignatureWebview}
            component={SignatureWebview}
          />
          <Stack.Screen
            name={NavigationName.NotificationHistoryScreen}
            component={NotificationHistory}
          />
        </Stack.Navigator>
      </ApplicationProvider>
    </>
  );
};

export default AppNavigation;
