import {useNavigation, useRoute} from '@react-navigation/native';
import {isEmpty, isNull, isUndefined} from 'lodash';
import {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Alert, ScrollView, TouchableOpacity, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import {
  getTitleProcessing,
  listStatus,
  mapStatus,
} from '../notification-list/components/NotificationItem/helper';
import {getListActionNotification, getPriority, listPriority} from './helper';
import styles from './styles';
import BottomSheetAuthorityAndForward from './components/AuthorityAndForward';
import {
  EnvelopeStatus,
  INotification,
  RoleNotification,
  SignType,
  StatusNotification,
} from '../../../model/interface/notification.interface';
import {useAppSelector} from '../../../hook/useRedux';
import TextCM from '../../../components/Text';
import React from 'react';
import {
  IconCreateDate,
  IconTabUser,
  IconPie,
  IconParties,
} from '../../../assets/images';
import BottomSheetCM from '../../../components/BottomSheet';
import ButtonCM from '../../../components/Button';
import HeaderCM from '../../../components/Header/HeaderCM';
import {NavigationName, Font, Color} from '../../../constants';
import {SizeDP} from '../../../constants/Size';
import {commonActions} from '../../../redux/slices';
import {DateUtils} from '../../../utils';
import {ActionItem, ActionType} from '../../../model/enum/enum';
import {
  useCreateNotiServices,
  useDocumentServices,
} from '../../../hook/apiHook/useApi';
import {IFieldsByHeader} from '../../../model/interface/common.interface';
import Toast from 'react-native-toast-message';
import useStoreNoti from '../store/store';

interface IRouterNotiDetail {
  notiId: string;
}

const NotificationDetail = () => {
  const route = useRoute<any>();
  const {notiId}: IRouterNotiDetail = route?.params;
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const [notification, setNotification] = useState<INotification>(
    {} as INotification,
  );
  const [dataGeneralInfor, setDataGeneralInfor] = useState<IFieldsByHeader[]>(
    [],
  );
  const [isVisiblePriority, setIsVisiblePriority] = useState<boolean>(false);
  const [isVisibleAuthoraztion, setIsVisibleAuthoraztion] =
    useState<boolean>(false);
  const [priorityState, setPriorityState] = useState<any>();
  const [actionTypeAuthorityOrForwards, setActionTypeAuthorityOrForwards] =
    useState<ActionType>();

  const [tempoiority, setTempoPiority] = useState('0');
  const [dataEkyc, setDataEkyc] = useState<any>();
  const [dataEnvelop, setDataEnvelop] = useState<any>();

  const {
    reLoadDataNotification,
    listNotifications,
    setReloadDataNotification,
    setListNotifications,
  } = useStoreNoti();
  const account = useAppSelector(state => state.account.dataAccount);

  const NotificationServices = useCreateNotiServices();
  const DocumentServices = useDocumentServices();

  const getDetailItem = async (data: INotification) => {
    const res = await DocumentServices.getEnvelopeDetailById(
      data.resourceId.split('_')[1],
    );
    const dataEnvelop = await DocumentServices.getEnvelopeDetailByIdV1(
      data.resourceId.split('_')[1],
    );
    setDataEnvelop(dataEnvelop[0]);
    if (account.email === dataEnvelop?.[0]?.requester?.contact?.email) {
      setDataEkyc(
        dataEnvelop?.[0].parties[0].recipients?.filter((recipi: any) =>
          recipi?.signTypes?.includes(SignType.EKYC),
        ),
      );
    } else {
      setDataEkyc(
        dataEnvelop?.[0].parties[0].recipients?.filter(
          (recipi: any) =>
            recipi?.contact?.email === account.email &&
            recipi?.signTypes?.includes(SignType.EKYC),
        ),
      );
    }
    setDataGeneralInfor(
      res.header.fields.filter(
        (item: any) =>
          item.id !== 'envSubmittedFrom' &&
          item.id !== 'envName' &&
          item.type !== 'Base64',
      ),
    );
  };
  useEffect(() => {
    getNotificationDetail();
  }, []);

  const getNotificationDetail = async () => {
    try {
      const res = await NotificationServices.getNotificationById(notiId);
      setNotification(res.data);
      getDetailItem(res.data);
      if (!isNull(res.data?.refId)) {
        setPriorityState(getPriority(res.data?.refId));
        setTempoPiority(res.data?.refId);
      }
    } catch (error) {}
  };

  const onChangeData = (item: INotification) => {
    const newListNoti = listNotifications.map(noti =>
      noti.id === item.id
        ? {
            ...item,
            refId: null,
          }
        : noti,
    );
    setListNotifications(newListNoti);
    setNotification(item);
  };

  const handleGetUrlContract = async () => {
    try {
      // const dataResp = await NotificationServices.getUrlViewContract(
      //   account!.email!.toLowerCase(),
      //   notification.resourceId.substr(4),
      // );
      // navigation.navigate(NavigationName.ViewPdfDocument, {
      //   // urlViewContract: dataResp.iframeUrl,
      //   envelopeId: dataEnvelop?.id,
      //   docId: dataEnvelop?.documents?.[0]?.id,
      // });
    } catch (error) {}
  };

  const handleAction = async (value: ActionItem) => {
    switch (value.type) {
      case ActionType.open:
        await handleGetUrlContract();
        break;
      case ActionType.history:
        navigation.navigate(NavigationName.NotificationHistoryScreen, {
          envId: notification?.resourceId?.substr(4),
        });
        break;
      case ActionType.priority:
        setIsVisiblePriority(true);
        break;
      case ActionType.authority:
        setActionTypeAuthorityOrForwards(ActionType.authority);
        setIsVisibleAuthoraztion(true);
        break;
      case ActionType.forward:
        setActionTypeAuthorityOrForwards(ActionType.forward);
        setIsVisibleAuthoraztion(true);
        break;
      default:
        break;
    }
  };

  const handleGetJwtToken = async (envelopeId: string, recipientId: string) => {
    try {
      await NotificationServices.getJwtTokenSignature({
        envelopeId: envelopeId,
        recipientId: recipientId,
        email: null,
        password: null,
      });
    } catch (error) {
      return null;
    }
  };

  const handleGoToWevview = async () => {
    try {
      const signTypes = JSON.parse(notification?.recipients[0]?.signTypes);
      const envelopeId = notification?.resourceId.substr(4);
      const recipientId = notification?.recipients[0]?.id;
      await handleGetJwtToken(envelopeId, recipientId);
      if (notification.role === RoleNotification.coordinator) {
        Alert.alert(
          'Thông báo',
          'Tính năng điều phối trên app đang phát triển',
        );
        // navigation.navigate(NavigationName.DetailCoordinationScreen, {
        //   envelopeId: envelopeId,
        //   recipientId: recipientId,
        //   notiId: notification?.id,
        // });
        return;
      }
      if (signTypes?.includes(SignType.EKYC)) {
        navigation.navigate(NavigationName.SignRuleScreen, {
          envelopeId: envelopeId,
          recipientId: recipientId,
        });
      } else {
        navigation.navigate(NavigationName.SignatureWebview, {
          envelopeId: envelopeId,
          recipientId: recipientId,
        });
      }
    } catch (error) {}
  };

  const handleSetPriority = (value: string) => async () => {
    try {
      await NotificationServices.setPriority(notification?.id, value);
      setPriorityState(getPriority(value));
      setTempoPiority(value);
      setIsVisiblePriority(false);
      setReloadDataNotification(!reLoadDataNotification);
      Toast.show({
        type: 'success',
        text1: t('NT.message.successSetPriority'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    } finally {
      setIsVisiblePriority(false);
    }
  };

  const renderItemAction = (value: ActionItem) => {
    return (
      <TouchableOpacity
        onPress={() => handleAction(value)}
        style={styles.btnAction}
        key={value.type}>
        <View style={styles.viewIcon}>{value.icon}</View>
        <TextCM style={styles.txtNameAction}>{value.name}</TextCM>
      </TouchableOpacity>
    );
  };

  const renderStatus = () => {
    const dataStatus = mapStatus(notification);
    const status = listStatus.find(item => item.type === dataStatus);

    return (
      <View>
        <TextCM
          style={[
            styles.txtStatus,
            {
              color: status?.color,
            },
          ]}>
          • {t(status?.title ?? '')}
        </TextCM>
      </View>
    );
  };

  const renderPriority = () => {
    if (isEmpty(priorityState) || isUndefined(priorityState)) return null;
    return (
      <View
        style={[styles.viewPriority, {backgroundColor: priorityState.bgColor}]}>
        <TextCM style={[styles.ctnText, {color: priorityState.textColor}]}>
          {priorityState.title}
        </TextCM>
      </View>
    );
  };

  const renderBottomSheetPriority = () => {
    const selectedPriority = getPriority(tempoiority);
    return (
      <>
        <TextCM style={{fontFamily: Font.InterSemiBold600}}>
          {t('NT.selectPriority')}
        </TextCM>
        <View style={styles.listPriority}>
          {listPriority.map(priority => (
            <TouchableOpacity
              onPress={() => setTempoPiority(priority.value)}
              key={priority.title}
              style={[
                styles.priority,
                {
                  backgroundColor: priority.bgColor,
                  borderColor: priority.textColor,
                },
                selectedPriority.value === priority.value && {
                  backgroundColor: priority.textColor,
                },
              ]}>
              <TextCM
                style={[
                  styles.txt16,
                  {color: priority.textColor},
                  selectedPriority.value === priority.value && {
                    color: Color.White,
                  },
                ]}>
                {priority.title}
              </TextCM>
            </TouchableOpacity>
          ))}
        </View>
        <View style={styles.groupButton}>
          <ButtonCM
            disabled={tempoiority === '0'}
            style={{flex: 1}}
            label={t('NT.deletePriority')}
            onPress={handleSetPriority('0')}
          />
          <ButtonCM
            style={{flex: 1}}
            label={t('CM.BtnConfirm')}
            onPress={handleSetPriority(tempoiority)}
          />
        </View>
      </>
    );
  };

  const isRenderStatus = () => {
    if (notification?.envelopeStatus !== EnvelopeStatus.processing) {
      return true;
    }
    if (
      notification?.status === StatusNotification.forwarded ||
      notification?.status === StatusNotification.delegated
    )
      return true;
    return false;
  };

  return (
    <>
      {notification && (
        <>
          <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
            <HeaderCM title={t('DC.TxtDetailDocument')} />
            <ScrollView style={{flex: 1, backgroundColor: '#fff'}}>
              <>
                <View style={styles.ctnHeader}>
                  {renderPriority()}
                  <View style={styles.body}>
                    <TextCM style={styles.txtTitle}>
                      {notification.resourceName}
                    </TextCM>
                  </View>
                  <View style={[styles.body]}>
                    <View style={styles.viewList}>
                      <View style={styles.viewItem}>
                        <View style={styles.viewName}>
                          <IconCreateDate
                            width={SizeDP(16)}
                            height={SizeDP(16)}
                          />
                          <TextCM style={styles.txtName}>
                            {t('NT.TxtReceivedDate')}
                          </TextCM>
                        </View>
                        <TextCM style={styles.txtValue}>
                          {DateUtils.convertDateToDDMMYYYYhhmm(
                            notification?.createdDate,
                          )}
                        </TextCM>
                      </View>
                      <View style={styles.viewItem}>
                        <View style={styles.viewName}>
                          <IconTabUser width={SizeDP(16)} height={SizeDP(16)} />
                          <TextCM style={styles.txtName}>
                            {t('NT.TxtSentFrom')}
                          </TextCM>
                        </View>
                        <TextCM style={styles.txtValue}>
                          {notification?.sendFrom}
                        </TextCM>
                      </View>
                      {isRenderStatus() && (
                        <View style={styles.viewItem}>
                          <View style={styles.viewName}>
                            <IconPie width={SizeDP(16)} height={SizeDP(16)} />
                            <TextCM style={styles.txtName}>
                              {t('NT.TxtStatus')}
                            </TextCM>
                          </View>
                          {renderStatus()}
                        </View>
                      )}
                      <View style={styles.viewItem}>
                        <View style={styles.viewName}>
                          <IconParties width={SizeDP(16)} height={SizeDP(16)} />
                          <TextCM style={styles.txtName}>
                            {t('NT.TxtDepartment')}
                          </TextCM>
                        </View>
                        <View style={styles.viewValueParties}>
                          {!isEmpty(
                            notification?.recipients?.[0]?.attrs
                              ?.primaryRecipient,
                          ) ? (
                            notification?.recipients?.[0]?.attrs?.primaryRecipient.map(
                              (item: any, index) => {
                                return (
                                  <TextCM style={styles.txtValue} key={index}>
                                    {item?.name}
                                  </TextCM>
                                );
                              },
                            )
                          ) : (
                            <TextCM style={styles.txtValue}>---</TextCM>
                          )}
                        </View>
                      </View>
                    </View>
                  </View>
                  <View style={styles.action}>
                    {getListActionNotification(
                      notification.envelopeStatus,
                      notification.status,
                    )?.map(renderItemAction)}
                  </View>
                </View>
                <View style={[styles.contain, {padding: 0}]}>
                  {/* {dataGeneralInfor?.length > 0 && (
                    <ListGeneralInfoDocument
                      dataEkyc={dataEkyc}
                      data={dataGeneralInfor}
                    />
                  )} */}
                </View>
              </>
            </ScrollView>
            <View style={{padding: SizeDP(16)}}>
              {!isRenderStatus() && (
                <ButtonCM
                  label={t(getTitleProcessing(notification.role))}
                  onPress={handleGoToWevview}
                />
              )}
            </View>
          </SafeAreaView>

          <BottomSheetCM
            title={t('NT.Priority')}
            isVisible={isVisiblePriority}
            onClose={() => setIsVisiblePriority(false)}
            renderContent={renderBottomSheetPriority()}
          />

          <BottomSheetCM
            title={
              actionTypeAuthorityOrForwards === ActionType.authority
                ? t('NT.personAuthority')
                : t('NT.forwardTo')
            }
            isVisible={isVisibleAuthoraztion}
            onClose={() => setIsVisibleAuthoraztion(false)}
            withKeyboardAvoidingView={true}
            renderContent={
              <BottomSheetAuthorityAndForward
                data={notification}
                onChangeData={onChangeData}
                onClose={() => setIsVisibleAuthoraztion(false)}
                actionTypeAuthorityOrForwardsProps={
                  actionTypeAuthorityOrForwards
                }
              />
            }
          />
        </>
      )}
    </>
  );
};

export default NotificationDetail;
