import {BASE_URL} from './httpClient';

export const documentService = (fetchRequest: any) => ({
  async getEnvelopeDetailById(id: string) {
    try {
      const endpoint = `/services/envelope/api/envelope/v2/model/${id}`;
      const res = await fetchRequest({
        url: `${BASE_URL}${endpoint}`,
        method: 'GET',
      });
      return Promise.resolve(res?.data);
    } catch (error) {
      console.error('Error getEnvelopeById:', error);
    }
  },

  async getEnvelopeDetailByIdV1(id: string) {
    try {
      const endpoint = `/services/envelope/api/envelope`;
      const res = await fetchRequest({
        url: `${BASE_URL}${endpoint}`,
        method: 'GET',
        params: {id},
      });
      return Promise.resolve(res?.data);
    } catch (error) {
      console.error('Error getEnvelopeByIdV1:', error);
    }
  },

  async getRecipentHistory(documentId: string, recipientId: string) {
    try {
      const uri = `/services/envelope/api/p/envelope/${documentId}/${documentId}/recipient/${recipientId}`;
      const res = await fetchRequest({
        url: `${BASE_URL}${uri}`,
        method: 'GET',
      });
      return Promise.resolve(res?.data);
    } catch (error) {
      console.error('Error getRecipentHistory:', error);
      return Promise.reject(error);
    }
  },

  async getServiceAvailability(custId: string) {
    try {
      const endpoint = '/services/uaa/api/service-availables/cust-id/' + custId;
      const res = await fetchRequest({
        url: `${BASE_URL}${endpoint}`,
        method: 'GET',
      });
      return Promise.resolve(res?.data);
    } catch (error) {
      console.error('Error getServiceAvailability:', error);
      return Promise.reject(error);
    }
  },

  async getModelEnvelopById(id: string) {
    try {
      const endpoint = `/services/envelope/api/envelope/v2/model/${id}`;
      const res = await fetchRequest({
        url: `${BASE_URL}${endpoint}`,
        method: 'GET',
      });
      return Promise.resolve(res?.data);
    } catch (error) {
      console.error('Error getModelEnvelopById:', error);
      return Promise.reject(error);
    }
  },
});
